// NAME: Charger | NOTE: runs straight at you, firing the whole way
function think(s, mem, squad) {
  return { move: "advance", attack: true };
}

// NAME: Turret | NOTE: stands still and shoots whenever it sees you
function think(s, mem, squad) {
  return { move: "hold", attack: s.canSee };
}

// NAME: Drunk | NOTE: stumbles in a random direction every step
function think(s, mem, squad) {
  const moves = ["advance", "retreat", "strafeL", "strafeR", "flankL", "flankR", "hold"];
  return { move: moves[Math.floor(Math.random() * moves.length)], attack: Math.random() < 0.3 };
}

// NAME: Coward | NOTE: backs off for a couple of seconds after taking a hit
function think(s, mem, squad) {
  if (s.hurtAgo < 70) return { move: "retreat", attack: s.canShoot };
  return { move: "advance", attack: s.canShoot };
}

// NAME: Dodging Turret | NOTE: strafe and reverse when hurt instead of standing
function think(s, mem, squad) {
  if (mem.dir === undefined) {
    mem.dir = Math.random() < 0.5 ? "strafeL" : "strafeR";
    mem.changed = s.aliveTics;
    mem.hurt = false;
  }
  const hurt = s.hurtAgo < 12 && !mem.hurt;
  if (hurt || s.aliveTics - mem.changed > 70) {
    mem.dir = mem.dir === "strafeL" ? "strafeR" : "strafeL";
    mem.changed = s.aliveTics;
  }
  mem.hurt = s.hurtAgo < 12;
  return { move: mem.dir, attack: s.canSee };
}

// NAME: Zigzag Charger | NOTE: keeps firing while randomizing forward flanking bursts
function think(s, mem, squad) {
  if (mem.move === undefined || s.aliveTics % 18 === 0) {
    const moves = ["advance", "flankL", "flankR"];
    mem.move = moves[Math.floor(Math.random() * moves.length)];
  }
  return { move: mem.move, attack: true };
}

// NAME: Weaving Charger | NOTE: keeps charging and firing, adds randomized flanking bursts
function think(s, mem, squad) {
  if (mem.tics === undefined || mem.tics <= 0) {
    const roll = Math.random();
    mem.move = roll < 0.65 ? "advance" : (roll < 0.825 ? "flankL" : "flankR");
    mem.tics = 6 + Math.floor(Math.random() * 10);
  }
  mem.tics--;
  return { move: mem.move, attack: true };
}

// NAME: Strafing Charger | NOTE: strafes at close range to dodge aimed fire
function think(s, mem, squad) {
  if (s.dist > 192) return { move: "advance", attack: true };
  return { move: s.uid % 2 ? "strafeL" : "strafeR", attack: true };
}

// NAME: Drunken Coward | NOTE: randomizes lateral dodges after hits instead of retreating
function think(s, mem, squad) {
  if (s.hurtAgo < 70) {
    if (mem.lastHurtAgo === undefined || s.hurtAgo < mem.lastHurtAgo) {
      mem.dodge = Math.random() < 0.5 ? "strafeL" : "strafeR";
    }
    mem.lastHurtAgo = s.hurtAgo;
    return { move: mem.dodge || "retreat", attack: s.canMelee || s.canShoot };
  }
  mem.lastHurtAgo = s.hurtAgo;
  const moves = ["advance", "advance", "flankL", "flankR"];
  return { move: moves[Math.floor(Math.random() * moves.length)], attack: s.canMelee || s.canShoot };
}

// NAME: Evasive Charger | NOTE: charges until targeted, then weaves randomly to evade fire
function think(s, mem, squad) {
  if (mem.turn === undefined || s.aliveTics >= mem.turn) {
    mem.dir = Math.random() < 0.5 ? "flankL" : "flankR";
    mem.turn = s.aliveTics + 12 + Math.floor(Math.random() * 18);
  }
  let move = "advance";
  if (s.aimOffset < 35 || s.hurtAgo < 5) move = mem.dir;
  if (s.canMelee) move = mem.dir === "flankL" ? "strafeL" : "strafeR";
  return { move: move, attack: true };
}

