// NAME: Shotgun Weaver | NOTE: combines weaving charges, hurt reversals, and shotgun-lane sidesteps
function think(s, mem, squad) {
  if (mem.dir === undefined) {
    mem.dir = Math.random() < 0.5 ? -1 : 1;
    mem.turn = 0;
    mem.hurt = false;
  }
  const newHurt = s.hurtAgo < 12 && !mem.hurt;
  if (newHurt || s.aliveTics >= mem.turn) {
    mem.dir = newHurt ? -mem.dir : (Math.random() < 0.5 ? -1 : 1);
    mem.turn = s.aliveTics + 12 + Math.floor(Math.random() * 18);
  }
  mem.hurt = s.hurtAgo < 12;
  const flank = mem.dir < 0 ? "flankL" : "flankR";
  const strafe = mem.dir < 0 ? "strafeL" : "strafeR";
  let move = "advance";
  if (s.aimOffset < 45 || s.hurtAgo < 5) move = flank;
  if (s.hurtAgo < 12) move = strafe;
  if (s.dist >= 240 && s.dist <= 440 && s.aimOffset < 45) move = strafe;
  if (s.canMelee) move = strafe;
  return { move: move, attack: true };
}

