// NAME: Scatterstep Charger | NOTE: jukes through shotgun range, reverses near crosshair
function think(s, mem, squad) {
  if (mem.dir === undefined) {
    mem.dir = s.uid % 2 === 0 ? "strafeL" : "strafeR";
    mem.changed = s.aliveTics;
