  const aimed = s.aimOffset < 18;
  const shotgun = s.playerWeapon === 2 || s.playerWeapon === 8;
  const danger = s.dist > 220 && s.dist < 460;
  const interval = danger ? 35 : 90;
  if (hurt || (aimed && !mem.aimed) || s.aliveTics - mem.changed > interval) {
    mem.dir = mem.dir === "strafeL" ? "strafeR" : "strafeL";
    mem.changed = s.aliveTics;
