  if (hurt) {
    mem.retreatUntil = s.aliveTics + (shotgun ? 50 : 35);
  }
  mem.hurt = s.hurtAgo < 12;
  mem.aimed = aimed;
  let move;
  if (s.aliveTics < mem.retreatUntil) {
    move = "retreat";
  } else if (s.dist > 460) {
    move = mem.dir === "strafeL" ? "flankL" : "flankR";
  } else if (s.dist < 85) {
    move = "advance";
